  "p.demo.f_kanban_t": "我的看板",
  "p.demo.f_kanban_d":
    "你在所有项目中的未完成任务，按状态分列。用鼠标或其菜单移动任务；任务状态会对所有人更新。",
  "p.demo.f_me_t": "我的工作",
  "p.demo.f_me_d":
    "按你所在时区的截止日期排列的相同任务：逾期、今天、本周、以后。",
  "p.demo.f_plans_t": "计划",
  "p.demo.f_plans_d":
    "十项虚构计划：诺斯盖特交通管理局的一个组合、三个项目群和六个项目。任选一项打开。",
  "p.demo.f_dashboard_t": "组合仪表盘",
  "p.demo.f_dashboard_d": "按类型和阶段显示的状态，附红、黄、绿计数。",
  "p.demo.f_gantt_t": "甘特图",
  "p.demo.f_gantt_d": "所有项目的进度显示在同一时间轴上。",
  "p.demo.f_milestones_t": "里程碑",
