  "p.demo.f_buffers_t": "缓冲管理",
  "p.demo.f_buffers_d": "已冻结的缓冲计划、发烧图和一项恢复措施。",
  "p.demo.f_pipeline_t": "鼓与管道",
  "p.demo.f_pipeline_d": "组合最依赖的技能池，以及建议的错开开始时间。",
